<?php
namespace App\Http\Controllers\Sales;use App\Http\Controllers\Controller;use App\Models\{CorporateAccount,GroupReservation,TravelAgent};use Illuminate\Http\Request;use Illuminate\Support\Str;
class GroupReservationController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('sales.groups',['groups'=>GroupReservation::where('property_id',$p)->with('company','agent')->latest()->paginate(40),'companies'=>CorporateAccount::where('property_id',$p)->where('status','active')->get(),'agents'=>TravelAgent::where('property_id',$p)->where('status','active')->get()]);}public function store(Request $r){$d=$r->validate(['group_name'=>'required|max:180','corporate_account_id'=>'nullable|exists:corporate_accounts,id','travel_agent_id'=>'nullable|exists:travel_agents,id','check_in_at'=>'required|date','check_out_at'=>'required|date|after:check_in_at','expected_guests'=>'required|integer|min:1','expected_rooms'=>'required|integer|min:1','estimated_total'=>'nullable|numeric|min:0','deposit_required'=>'nullable|numeric|min:0','notes'=>'nullable|string']);$g=GroupReservation::create([...$d,'property_id'=>auth()->user()->property_id,'reference'=>'GRP-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'created_by'=>auth()->id()]);return back()->with('success','Group reservation '.$g->reference.' created.');}}
